package com.orderflow.delivery.outbox;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import com.orderflow.delivery.config.OutboxProperties;import com.orderflow.events.EventMetadata;import java.sql.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;
@Repository public class OutboxStore{
 private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final OutboxProperties properties;private final Clock clock;
 public OutboxStore(JdbcTemplate jdbc,ObjectMapper mapper,OutboxProperties properties,Clock clock){this.jdbc=jdbc;this.mapper=mapper;this.properties=properties;this.clock=clock;}
 public void enqueue(String topic,UUID key,Object event,EventMetadata m){try{Instant now=Instant.now(clock);jdbc.update("INSERT INTO outbox_event(id,aggregate_type,aggregate_id,event_type,event_version,topic,message_key,payload,correlation_id,causation_id,status,attempts,available_at,created_at) VALUES(?,?,?,?,?,?,?,CAST(? AS jsonb),?,?,'NEW',0,?,?)",m.eventId(),m.aggregateType(),m.aggregateId(),m.eventType().name(),m.eventVersion(),topic,key.toString(),mapper.writeValueAsString(event),m.correlationId(),m.causationId(),Timestamp.from(now),Timestamp.from(now));}catch(JsonProcessingException e){throw new IllegalStateException("Unable to serialize delivery event",e);}}
 @Transactional public List<OutboxMessage> claim(String owner){Instant now=Instant.now(clock);List<OutboxMessage> rows=jdbc.query("SELECT id,topic,message_key,event_type,event_version,payload::text,attempts FROM outbox_event WHERE(status='NEW' AND available_at<=?)OR(status='IN_PROGRESS' AND locked_at<?)ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT ?",this::map,Timestamp.from(now),Timestamp.from(now.minus(properties.lockTimeout())),properties.batchSize());rows.forEach(r->jdbc.update("UPDATE outbox_event SET status='IN_PROGRESS',locked_at=?,locked_by=? WHERE id=?",Timestamp.from(now),owner,r.id()));return rows;}
 public void published(UUID id,String owner){jdbc.update("UPDATE outbox_event SET status='PUBLISHED',published_at=?,locked_at=NULL,locked_by=NULL,last_error_code=NULL WHERE id=? AND locked_by=?",Timestamp.from(Instant.now(clock)),id,owner);}
 public void failed(OutboxMessage m,String owner,String code){int a=m.attempts()+1;jdbc.update("UPDATE outbox_event SET status=?,attempts=?,available_at=?,last_error_code=?,locked_at=NULL,locked_by=NULL WHERE id=? AND locked_by=?",a>=properties.maxAttempts()?"FAILED":"NEW",a,Timestamp.from(Instant.now(clock).plus(backoff(properties.retryBaseDelay(),a))),code.substring(0,Math.min(code.length(),200)),m.id(),owner);}
 public long backlog(){Long n=jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE status IN('NEW','IN_PROGRESS')",Long.class);return n==null?0:n;}public long failedCount(){Long n=jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE status='FAILED'",Long.class);return n==null?0:n;}
 public static Duration backoff(Duration base,int attempts){return base.multipliedBy(1L<<Math.min(Math.max(attempts-1,0),10));}
 private OutboxMessage map(ResultSet r,int i)throws SQLException{return new OutboxMessage(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getInt(5),r.getString(6),r.getInt(7));}
}
